sys_variable_value.value:
/**
 * Creates the initial investigation tasks for a new case, derived from
 * bfd_TriageEngine.recommendActions(). Due dates come from case priority
 * (P1 +4h, P2 +24h, P3 +72h, P4 +120h).
 */
(function execute(inputs, outputs) {
    outputs.taskCount = new bfd_FlowSupport().createInitialTasks(inputs.caseSysId);
})(inputs, outputs);

